package com.secure.documentwallet;

import android.app.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.os.Bundle;import android.provider.MediaStore;import android.view.*;import android.widget.*;import androidx.activity.result.*;import androidx.activity.result.contract.ActivityResultContracts;import androidx.fragment.app.FragmentActivity;import java.io.*;import java.util.*;import java.util.concurrent.*;

/** Guided front/back gallery import with an adjustable crop before encryption. */
public class CardImportWizardActivity extends FragmentActivity {
 private final ExecutorService io=Executors.newSingleThreadExecutor();private final ArrayList<Uri> pages=new ArrayList<>();private VaultRepository repo;private String group;private CropView crop;private TextView heading,choose;private int stage=1;private boolean saved;
 private final ActivityResultLauncher<Intent> gallery=registerForActivityResult(new ActivityResultContracts.StartActivityForResult(),result->{if(result.getResultCode()==RESULT_OK&&result.getData()!=null&&result.getData().getData()!=null)loadPhoto(result.getData().getData());});
 @Override public void onCreate(Bundle state){super.onCreate(state);Ui.safeScreen(this);if(!Session.valid()){finish();return;}group=getIntent().getStringExtra("group");if(!DocumentGroups.CARDS.equals(group)&&!DocumentGroups.ID.equals(group)){finish();return;}repo=new VaultRepository(this);buildCrop();getWindow().getDecorView().post(this::openGallery);}
 private void buildCrop(){LinearLayout root=Ui.column(this);root.setBackgroundColor(0xff061f3b);root.setPadding(Ui.dp(this,16),Ui.dp(this,12),Ui.dp(this,16),Ui.dp(this,16));LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);TextView close=Ui.text(this,"×",31,Color.WHITE);close.setGravity(Gravity.CENTER);close.setContentDescription("Cancel Import");close.setOnClickListener(v->finish());bar.addView(close,new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48)));heading=Ui.title(this,stage==1?"Step 1 · Crop The Front":"Step 2 · Crop The Back",23);heading.setTextColor(Color.WHITE);heading.setGravity(Gravity.CENTER);bar.addView(heading,new LinearLayout.LayoutParams(0,-2,1));TextView step=Ui.text(this,stage+" / 3",13,0xffd8efea);step.setGravity(Gravity.CENTER);bar.addView(step,new LinearLayout.LayoutParams(Ui.dp(this,54),Ui.dp(this,48)));root.addView(bar);crop=new CropView();FrameLayout frame=new FrameLayout(this);frame.setBackground(Ui.bg(0xff0b304c,Ui.dp(this,20)));frame.setPadding(Ui.dp(this,7),Ui.dp(this,7),Ui.dp(this,7),Ui.dp(this,7));frame.addView(crop,new FrameLayout.LayoutParams(-1,-1));LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(-1,0,1);fp.setMargins(0,Ui.dp(this,9),0,Ui.dp(this,10));root.addView(frame,fp);choose=Ui.pill(this,"Choose "+(stage==1?"Front":"Back")+" Photo",0xff0b5f75);choose.setOnClickListener(v->openGallery());root.addView(choose,new LinearLayout.LayoutParams(-1,Ui.dp(this,48)));LinearLayout actions=new LinearLayout(this);TextView rotate=action("↻\nRotate",0xfff5f7f6,Ui.INK),reset=action("⌗\nReset Crop",0xfff5f7f6,Ui.INK),use=action("✓\nUse "+(stage==1?"Front":"Back"),Ui.TEAL,Color.WHITE);rotate.setOnClickListener(v->crop.rotate());reset.setOnClickListener(v->crop.resetCrop());use.setOnClickListener(v->acceptCrop());for(TextView item:new TextView[]{rotate,reset,use}){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,Ui.dp(this,66),item==use?1.25f:1);p.setMargins(Ui.dp(this,4),Ui.dp(this,10),Ui.dp(this,4),0);actions.addView(item,p);}root.addView(actions);setContentView(root);}
 private TextView action(String label,int background,int foreground){TextView view=Ui.text(this,label,13,foreground);view.setGravity(Gravity.CENTER);view.setTypeface(null,android.graphics.Typeface.BOLD);view.setBackground(Ui.bg(background,Ui.dp(this,15)));return view;}
 private void openGallery(){Intent intent=new Intent(Intent.ACTION_PICK,MediaStore.Images.Media.EXTERNAL_CONTENT_URI).setType("image/*");Intent samsung=new Intent(intent).setPackage("com.sec.android.gallery3d");gallery.launch(samsung.resolveActivity(getPackageManager())!=null?samsung:intent);}
 private void loadPhoto(Uri uri){choose.setText("Loading Photo…");io.execute(()->{try{BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;try(InputStream input=getContentResolver().openInputStream(uri)){BitmapFactory.decodeStream(input,null,bounds);}int sample=1;while(Math.max(bounds.outWidth,bounds.outHeight)/sample>3000)sample*=2;BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=sample;Bitmap bitmap;try(InputStream input=getContentResolver().openInputStream(uri)){bitmap=BitmapFactory.decodeStream(input,null,options);}if(bitmap==null)throw new IOException();runOnUiThread(()->{crop.setBitmap(bitmap);choose.setText("Choose A Different Photo");});}catch(Exception error){runOnUiThread(()->{choose.setText("Choose Photo");Ui.toast(this,"Could Not Open This Photo");});}});}
 private void acceptCrop(){Bitmap result=crop.cropped();if(result==null){Ui.toast(this,"Choose A Photo And Adjust The Crop First");return;}ProgressDialog wait=new ProgressDialog(this);wait.setCancelable(false);wait.setMessage("Preparing Cropped Side…");wait.show();io.execute(()->{try{File directory=new File(getCacheDir(),"card_import");if(!directory.exists())directory.mkdirs();File file=new File(directory,"side-"+stage+"-"+System.nanoTime()+".jpg");try(OutputStream out=new BufferedOutputStream(new FileOutputStream(file))){result.compress(Bitmap.CompressFormat.JPEG,96,out);}result.recycle();pages.add(Uri.fromFile(file));runOnUiThread(()->{wait.dismiss();if(stage==1)askForBack();else showTitle();});}catch(Exception error){result.recycle();runOnUiThread(()->{wait.dismiss();Ui.toast(this,"Could Not Prepare This Crop");});}});}
 private void askForBack(){new AlertDialog.Builder(this).setTitle("Does This Have A Back?").setMessage("Add the reverse side now, or continue with the front only.").setCancelable(false).setNegativeButton("No · Continue",(d,w)->showTitle()).setPositiveButton("Yes · Add Back",(d,w)->{stage=2;crop.release();buildCrop();getWindow().getDecorView().post(this::openGallery);}).show();}
 private void showTitle(){if(crop!=null)crop.release();LinearLayout root=Ui.column(this);root.setGravity(Gravity.CENTER);root.setPadding(Ui.dp(this,24),Ui.dp(this,22),Ui.dp(this,24),Ui.dp(this,24));root.setBackgroundColor(0xfff2f7f5);TextView step=Ui.text(this,"STEP 3 OF 3",12,Ui.TEAL);step.setTypeface(null,android.graphics.Typeface.BOLD);step.setGravity(Gravity.CENTER);root.addView(step);TextView title=Ui.title(this,"Name Your "+(DocumentGroups.CARDS.equals(group)?"Bank Card":"ID Or Permit"),26);title.setTextColor(0xff092f46);title.setGravity(Gravity.CENTER);title.setPadding(0,Ui.dp(this,10),0,Ui.dp(this,6));root.addView(title);TextView summary=Ui.text(this,pages.size()==2?"Front and back are cropped and ready.":"The cropped front is ready.",14,Ui.MUTED);summary.setGravity(Gravity.CENTER);summary.setPadding(0,0,0,Ui.dp(this,22));root.addView(summary);EditText name=Ui.field(this,DocumentGroups.CARDS.equals(group)?"Card name":"ID or permit name",false);root.addView(name,new LinearLayout.LayoutParams(-1,Ui.dp(this,56)));TextView save=Ui.pill(this,"Encrypt And Save",Ui.TEAL);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,Ui.dp(this,54));sp.topMargin=Ui.dp(this,14);root.addView(save,sp);TextView cancel=Ui.text(this,"Cancel Import",14,0xffb3261e);cancel.setGravity(Gravity.CENTER);cancel.setPadding(0,Ui.dp(this,18),0,Ui.dp(this,18));cancel.setOnClickListener(v->finish());root.addView(cancel);save.setOnClickListener(v->{String value=name.getText().toString().trim();if(value.isEmpty()){name.setError("Add a title");return;}save.setEnabled(false);io.execute(()->{try{repo.add(value,group,new ArrayList<>(pages));saved=true;cleanup();runOnUiThread(()->{Ui.toast(this,"Card Encrypted And Saved");finish();});}catch(Exception error){runOnUiThread(()->{save.setEnabled(true);Ui.toast(this,"Could Not Save This Card");});}});});setContentView(root);name.requestFocus();getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);}
 private void cleanup(){for(Uri uri:pages)if("file".equals(uri.getScheme()))new File(uri.getPath()).delete();pages.clear();}
 @Override public boolean dispatchTouchEvent(MotionEvent event){if(Session.valid())Session.touch();return super.dispatchTouchEvent(event);}
 @Override protected void onDestroy(){super.onDestroy();io.shutdownNow();if(crop!=null)crop.release();if(!saved)cleanup();}

 private final class CropView extends View {
  private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG),shade=new Paint(),line=new Paint(Paint.ANTI_ALIAS_FLAG);private Bitmap bitmap;private final RectF imageRect=new RectF(),cropRect=new RectF();private int handle=-1;private float lastX,lastY;
  CropView(){super(CardImportWizardActivity.this);shade.setColor(0x99000000);line.setColor(0xff35d5c4);line.setStyle(Paint.Style.STROKE);line.setStrokeWidth(Ui.dp(CardImportWizardActivity.this,2));setLayerType(View.LAYER_TYPE_SOFTWARE,null);}
  void setBitmap(Bitmap value){release();bitmap=value;resetCrop();}
  void resetCrop(){if(bitmap==null||getWidth()==0){invalidate();return;}fit();cropRect.set(imageRect);float dx=imageRect.width()*.035f,dy=imageRect.height()*.035f;cropRect.inset(dx,dy);invalidate();}
  void fit(){if(bitmap==null)return;float scale=Math.min((float)getWidth()/bitmap.getWidth(),(float)getHeight()/bitmap.getHeight());float width=bitmap.getWidth()*scale,height=bitmap.getHeight()*scale;imageRect.set((getWidth()-width)/2f,(getHeight()-height)/2f,(getWidth()+width)/2f,(getHeight()+height)/2f);}
  @Override protected void onSizeChanged(int w,int h,int oldW,int oldH){if(bitmap!=null)resetCrop();}
  @Override protected void onDraw(Canvas canvas){super.onDraw(canvas);if(bitmap==null){paint.setColor(0xffd8efea);paint.setTextSize(Ui.dp(CardImportWizardActivity.this,16));canvas.drawText("Choose A Photo To Begin",Ui.dp(CardImportWizardActivity.this,25),getHeight()/2f,paint);return;}fit();canvas.drawBitmap(bitmap,null,imageRect,paint);canvas.drawRect(imageRect.left,imageRect.top,imageRect.right,cropRect.top,shade);canvas.drawRect(imageRect.left,cropRect.bottom,imageRect.right,imageRect.bottom,shade);canvas.drawRect(imageRect.left,cropRect.top,cropRect.left,cropRect.bottom,shade);canvas.drawRect(cropRect.right,cropRect.top,imageRect.right,cropRect.bottom,shade);canvas.drawRect(cropRect,line);for(int i=1;i<3;i++){float x=cropRect.left+cropRect.width()*i/3f,y=cropRect.top+cropRect.height()*i/3f;canvas.drawLine(x,cropRect.top,x,cropRect.bottom,line);canvas.drawLine(cropRect.left,y,cropRect.right,y,line);}paint.setColor(Color.WHITE);paint.setStyle(Paint.Style.FILL);for(float[] point:handles())canvas.drawCircle(point[0],point[1],Ui.dp(CardImportWizardActivity.this,8),paint);paint.setColor(0xff35d5c4);for(float[] point:handles())canvas.drawCircle(point[0],point[1],Ui.dp(CardImportWizardActivity.this,5),paint);}
  private float[][] handles(){return new float[][]{{cropRect.left,cropRect.top},{cropRect.right,cropRect.top},{cropRect.right,cropRect.bottom},{cropRect.left,cropRect.bottom}};}
  @Override public boolean onTouchEvent(MotionEvent event){float x=event.getX(),y=event.getY();if(event.getActionMasked()==MotionEvent.ACTION_DOWN){handle=nearest(x,y);lastX=x;lastY=y;return true;}if(event.getActionMasked()==MotionEvent.ACTION_MOVE){float dx=x-lastX,dy=y-lastY;if(handle>=0)moveHandle(handle,dx,dy);else if(cropRect.contains(lastX,lastY)){cropRect.offset(dx,dy);clamp();}lastX=x;lastY=y;invalidate();return true;}if(event.getActionMasked()==MotionEvent.ACTION_UP){performClick();handle=-1;return true;}return true;}
  @Override public boolean performClick(){super.performClick();return true;}
  private int nearest(float x,float y){float max=Ui.dp(CardImportWizardActivity.this,38),best=max*max;int nearest=-1,index=0;for(float[] point:handles()){float distance=(x-point[0])*(x-point[0])+(y-point[1])*(y-point[1]);if(distance<best){best=distance;nearest=index;}index++;}return nearest;}
  private void moveHandle(int which,float dx,float dy){float min=Ui.dp(CardImportWizardActivity.this,70);if(which==0||which==3)cropRect.left=Math.min(cropRect.left+dx,cropRect.right-min);else cropRect.right=Math.max(cropRect.right+dx,cropRect.left+min);if(which==0||which==1)cropRect.top=Math.min(cropRect.top+dy,cropRect.bottom-min);else cropRect.bottom=Math.max(cropRect.bottom+dy,cropRect.top+min);clamp();}
  private void clamp(){float dx=0,dy=0;if(cropRect.left<imageRect.left)dx=imageRect.left-cropRect.left;if(cropRect.right>imageRect.right)dx=imageRect.right-cropRect.right;if(cropRect.top<imageRect.top)dy=imageRect.top-cropRect.top;if(cropRect.bottom>imageRect.bottom)dy=imageRect.bottom-cropRect.bottom;cropRect.offset(dx,dy);}
  void rotate(){if(bitmap==null)return;Matrix matrix=new Matrix();matrix.postRotate(90);Bitmap rotated=Bitmap.createBitmap(bitmap,0,0,bitmap.getWidth(),bitmap.getHeight(),matrix,true);bitmap.recycle();bitmap=rotated;resetCrop();}
  Bitmap cropped(){if(bitmap==null)return null;fit();int left=Math.max(0,Math.round((cropRect.left-imageRect.left)/imageRect.width()*bitmap.getWidth())),top=Math.max(0,Math.round((cropRect.top-imageRect.top)/imageRect.height()*bitmap.getHeight())),right=Math.min(bitmap.getWidth(),Math.round((cropRect.right-imageRect.left)/imageRect.width()*bitmap.getWidth())),bottom=Math.min(bitmap.getHeight(),Math.round((cropRect.bottom-imageRect.top)/imageRect.height()*bitmap.getHeight()));if(right-left<10||bottom-top<10)return null;return Bitmap.createBitmap(bitmap,left,top,right-left,bottom-top);}
  void release(){if(bitmap!=null&&!bitmap.isRecycled())bitmap.recycle();bitmap=null;}
 }
}
